import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs['target_snapshot'].copy()
    cdc = inputs['cdc_events'].copy()
    watermark = inputs['watermark']

    high_ts = watermark['high_ts'].iloc[0]

    # Build initial state keyed by user_id
    state = {}
    for _, row in target.iterrows():
        state[row['user_id']] = {
            'email': row['email'],
            'status': row['status'],
            'status_ts': row['status_ts'],
        }

    # Only events strictly after the watermark are new
    new_events = cdc[cdc['event_ts'] > high_ts].copy()

    # Global sequential order by (event_ts, event_seq) -- stable sort to
    # preserve any pre-existing ordering ties deterministically.
    new_events = new_events.sort_values(
        by=['event_ts', 'event_seq'], kind='mergesort'
    )

    for _, ev in new_events.iterrows():
        uid = ev['user_id']
        op = ev['op']
        ts = ev['event_ts']
        email = ev['email']

        cur = state.get(uid)

        if op == 'D':
            if cur is None:
                # No prior row to preserve email from; fall back to event email.
                state[uid] = {
                    'email': email,
                    'status': 'DELETED',
                    'status_ts': ts,
                }
            else:
                # Email is preserved as of deletion: keep existing email.
                state[uid] = {
                    'email': cur['email'],
                    'status': 'DELETED',
                    'status_ts': ts,
                }
        elif op == 'U':
            if cur is None or cur['status'] == 'ACTIVE':
                state[uid] = {
                    'email': email,
                    'status': 'ACTIVE',
                    'status_ts': ts,
                }
            else:
                # Currently DELETED: resurrection only if strictly more than
                # 7 days have passed since the deletion's status_ts.
                threshold = cur['status_ts'] + pd.Timedelta(days=7)
                if ts > threshold:
                    state[uid] = {
                        'email': email,
                        'status': 'ACTIVE',
                        'status_ts': ts,
                    }
                else:
                    # Sticky deletion window: discard the update.
                    pass

    rows = [
        {
            'user_id': uid,
            'email': v['email'],
            'status': v['status'],
            'status_ts': v['status_ts'],
        }
        for uid, v in state.items()
    ]

    result = pd.DataFrame(rows, columns=['user_id', 'email', 'status', 'status_ts'])

    return {'new_snapshot': result}
